with RecentPayments as (select *, concat(method, ' ', status) as method_status from payments where not ((status in ('SUCCESS', 'REFUNDED', 'FAILED') and status in ('FAILED', 'REFUNDED')) or amount <= 1120)), payments_stats as (select year(paid_at) as paid_year, method, max(amount) - min(amount) as amount_range, min(paid_at) as first_paid_at from RecentPayments group by year(paid_at), method) select paid_year, method, amount_range, first_paid_at from payments_stats where amount_range > 42
